import re
import string
import gensim
from bs4 import BeautifulSoup


class HtmlUtil:

    SPACE_MARK = '-SPACE-'
    JSON_MARK = '-JSON-'
    MARKUP_LANGUAGE_MARK = '-MARKUP_LANGUAGE-'
    URL_MARK = '-URL-'
    NUMBER_MARK = '-NUMBER-'
    TRACE_MARK = '-TRACE-'
    COMMAND_MARK = '-COMMAND-'
    COMMENT_MARK = '-COMMENT-'
    CODE_MARK = '-CODE-'

    def __init__(self):
        self.space_mark = self.SPACE_MARK
        self.json_mark = self.JSON_MARK
        self.markup_language_mark = self.MARKUP_LANGUAGE_MARK
        self.url_mark = self.URL_MARK
        self.number_mark = self.NUMBER_MARK
        self.trace_mark = self.TRACE_MARK
        self.command_mark = self.COMMAND_MARK
        self.comment_mark = self.COMMENT_MARK
        self.code_mark = self.CODE_MARK

    @staticmethod
    def _format_line_feed(text):
        return re.sub(r'\n+', '\n', text)

    def _process_code_tags(self, soup):
        code_tag = soup.find_all(name=['pre', 'blockquote'])
        for tag in code_tag:
            tag.string = self.code_mark

    def _process_list_items(self, soup):
        ul_ol_group = soup.find_all(name=['ul', 'ol'])
        for ul_ol_item in ul_ol_group:
            li_group = ul_ol_item.find_all('li')
            for li_item in li_group:
                li_item_text = li_item.get_text().strip()
                if not li_item_text:
                    continue
                li_item.string = self._format_list_item_text(li_item_text)

    def _format_list_item_text(self, li_item_text):
        if li_item_text[-1] in string.punctuation:
            return '[{0}]{1}'.format('-', li_item_text)
        return '[{0}]{1}.'.format('-', li_item_text)

    def _process_paragraphs(self, soup):
        p_group = soup.find_all(name=['p'])
        for p_item in p_group:
            p_item_text = p_item.get_text().strip()
            if not p_item_text:
                continue
            p_item.string = self._format_paragraph_text(p_item, p_item_text)

    def _format_paragraph_text(self, p_item, p_item_text):
        if p_item_text[-1] in string.punctuation:
            return p_item_text
        next_sibling = p_item.find_next_sibling()
        if next_sibling and self.code_mark in next_sibling.get_text():
            return p_item_text + ':'
        return p_item_text + '.'

    def _is_empty_text(self, text):
        return text is None or len(text) == 0

    def format_line_html_text(self, html_text):
        if self._is_empty_text(html_text):
            return ''
        soup = BeautifulSoup(html_text, 'lxml')

        self._process_code_tags(soup)
        self._process_list_items(soup)
        self._process_paragraphs(soup)

        clean_text = gensim.utils.decode_htmlentities(soup.get_text())
        return self._format_line_feed(clean_text)

    def _collect_code_tags(self, html_text):
        soup = BeautifulSoup(html_text, 'lxml')
        code_tag = soup.find_all(name=['pre', 'blockquote'])
        return code_tag

    def _has_code_marker(self, text):
        return self.code_mark in text

    def _count_code_markers(self, text):
        return text.count(self.code_mark)

    def _extract_code_blocks(self, html_text, code_count):
        soup = BeautifulSoup(html_text, 'lxml')
        code_tag = soup.find_all(name=['pre', 'blockquote'])
        code_list = []
        for code_index in range(code_count):
            code = code_tag[code_index].get_text()
            if code:
                code_list.append(code)
        return code_list

    def extract_code_from_html_text(self, html_text):
        text_with_code_tag = self.format_line_html_text(html_text)

        if not self._has_code_marker(text_with_code_tag):
            return []

        code_count = self._count_code_markers(text_with_code_tag)
        return self._extract_code_blocks(html_text, code_count)
